export interface WidgetDefinition {
  id: string;
  labelEn: string;
  labelPt: string;
  descriptionEn: string;
  descriptionPt: string;
  icon: string;
  /** Default width in grid columns (1 = narrow, 2 = wide) */
  defaultCols: 1 | 2;
  /** Maximum width in grid columns — widget won't exceed this span */
  maxCols: 1 | 2 | 3 | 4;
  /** Minimum height in px */
  minHeight: number;
}

export interface WidgetInstance {
  id: string;
  /** references WidgetDefinition.id */
  widgetId: string;
}

